# app.pyimport refrom typing import List, Optional, Tupleimport cv2import numpy as npimport uvicornfrom fastapi import FastAPI, File, HTTPException, UploadFilefrom fastapi.middleware.cors import CORSMiddlewarefrom fastapi.responses import JSONResponsefrom pydantic import BaseModelfrom ultralytics import YOLO# ==========================# 1. Model paths# ==========================PLATE_MODEL_PATH = "models/best_yolo_mask.pt"   # plate detectorOCR_MODEL_PATH = "models/best_ocr.pt"           # OCR modelprint("📦 Loading models...")plate_model = YOLO(PLATE_MODEL_PATH)ocr_model = YOLO(OCR_MODEL_PATH)# ==========================# 2. FastAPI + Swagger metadata# ==========================tags_metadata = [    {        "name": "system",        "description": "Service/system endpoints used for monitoring.",    },    {        "name": "plates",        "description": (            "Endpoints for Ukrainian license plate recognition.\n\n"            "Endpoint `/plates/recognize-two` expects **exactly two** "            "files under the `images` key in `multipart/form-data`."        ),    },]app = FastAPI(    title="Plate OCR API",    version="0.1.0",    description="Service for license plate detection and text recognition (YOLO + OCR).",    openapi_tags=tags_metadata,    docs_url="/docs",    redoc_url="/redoc",    openapi_url="/openapi.json",)app.add_middleware(    CORSMiddleware,    allow_origins=["*"],      # tighten this on prod    allow_credentials=True,    allow_methods=["*"],    allow_headers=["*"],)# ==========================# 3. Pydantic models (for Swagger)# ==========================class PlateItem(BaseModel):    index: int    filename: Optional[str] = None    success: bool    plate: Optional[str] = None    error: Optional[str] = Noneclass RecognizeTwoResponse(BaseModel):    results: List[PlateItem]# ==========================# 4. Plate crop# ==========================def crop_plate(img: np.ndarray, result, pad: int = 10) -> Optional[np.ndarray]:    """    Crop plate region from YOLO boxes with a small padding.    Uses the box with the highest confidence.    """    boxes = result.boxes    if len(boxes) == 0:        return None    best_idx = boxes.conf.argmax()    x1, y1, x2, y2 = boxes.xyxy[best_idx].tolist()    h, w = img.shape[:2]    x1 = max(int(x1) - pad, 0)    y1 = max(int(y1) - pad, 0)    x2 = min(int(x2) + pad, w)    y2 = min(int(y2) + pad, h)    print(f"📐 Plate crop: x1={x1}, y1={y1}, x2={x2}, y2={y2}, w={x2-x1}, h={y2-y1}")    return img[y1:y2, x1:x2]# ==========================# 5. YOLO-OCR → text# ==========================def ocr_to_text(ocr_result) -> str:    """    Convert YOLO OCR boxes to final plate text.    Steps:    1) collect (x_center, y_center, char)    2) sort by y → group into lines    3) sort each line by x    4) join characters    5) try to match Ukrainian format AA1234BB    """    chars = []    for box in ocr_result.boxes:        x_center = float(box.xywh[0][0])        y_center = float(box.xywh[0][1])        cls = int(box.cls[0])        char = ocr_model.names[cls]  # ['0', '1', ..., 'Z']        chars.append((x_center, y_center, char))    if not chars:        return ""    # sort by y (vertical)    chars = sorted(chars, key=lambda x: x[1])    # group into lines by y    lines: List[List[Tuple[float, float, str]]] = []    current_line = [chars[0]]    for c in chars[1:]:        if abs(c[1] - current_line[-1][1]) < 20:  # same row threshold            current_line.append(c)        else:            lines.append(current_line)            current_line = [c]    lines.append(current_line)    # sort each line by x    for i in range(len(lines)):        lines[i] = sorted(lines[i], key=lambda x: x[0])    # raw text    final_text = " ".join("".join(c[2] for c in line) for line in lines)    raw = final_text.replace(" ", "")    print("🔤 Raw YOLO-OCR sequence:", raw)    # Ukrainian plate format: AA1234B / AA1234BB    m = re.search(r"[A-Z]{2}\d{4}[A-Z]{1,2}", raw)    plate = m.group(0) if m else raw    print("Plate text (final YOLO-OCR):", plate)    return plate# ==========================# 6. Full pipeline on numpy image# ==========================def recognize_plate_np(img: np.ndarray) -> Tuple[Optional[np.ndarray], Optional[object], str]:    """    Full pipeline for a loaded numpy image:    detector → crop → OCR → plate text.    """    if img is None:        raise ValueError("Empty image given")    # 1. Detect plate    det_res = plate_model(img)[0]    if len(det_res.boxes) == 0:        print("No plate detected")        return None, None, ""    # 2. Crop plate region    plate_crop = crop_plate(img, det_res)    if plate_crop is None or plate_crop.size == 0:        print("Cropping failed")        return None, None, ""    # 3. Run OCR model on the crop    ocr_res = ocr_model(plate_crop)[0]    # 4. Convert boxes to text    plate_text = ocr_to_text(ocr_res)    return plate_crop, ocr_res, plate_text# ==========================# 7. FastAPI endpoints# ==========================@app.get(    "/health",    tags=["system"],    summary="Health-check endpoint",)def health():    """Simple endpoint to check that the service is alive."""    return {"status": "ok"}@app.post(    "/plates/recognize-two",    tags=["plates"],    summary="Recognize plates on two images",    response_model=RecognizeTwoResponse,)async def recognize_two_plates(    images: List[UploadFile] = File(        ...,        description=(            "Exactly two image files. "            "Send as `multipart/form-data` with key `images` (twice)."        ),    ),):    """    Accepts **exactly 2** images and returns recognized plate text for each of them.    """    if len(images) != 2:        raise HTTPException(status_code=400, detail="Exactly 2 images must be sent")    results: List[PlateItem] = []    for idx, upload in enumerate(images):        content = await upload.read()        np_bytes = np.frombuffer(content, np.uint8)        img = cv2.imdecode(np_bytes, cv2.IMREAD_COLOR)        if img is None:            results.append(                PlateItem(                    index=idx,                    filename=upload.filename,                    success=False,                    plate=None,                    error="Cannot decode image",                )            )            continue        _, _, text = recognize_plate_np(img)        results.append(            PlateItem(                index=idx,                filename=upload.filename,                success=bool(text),                plate=text or None,                error=None if text else "Plate not recognized",            )        )    return RecognizeTwoResponse(results=results)# Local run: `python app.py`if __name__ == "__main__":    uvicorn.run("app:app", host="0.0.0.0", port=8000, reload=True)